"""OpenNavigation route family for the Windows platform.

Every OpenNavigation instruction on this platform finishes on a route the agent
has drawn in the route editor.  This base decides the task from that final
route -- its ordered locations, its travel mode and its departure setting --
together with the route editor that is left on screen.  How many routes were
tried on the way there, and in which order, is not part of the decision.

The route the instruction ends on is taken from the task's own final
instruction step, cross-checked against the route table the task declares.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus

EVENT_LOG_PATH = r"C:\Apps\OpenNavigation\opennavigation-events.jsonl"


class TaskBoundOpenNavigationEventEvaluator(BaseEvaluator):
    """Decide an OpenNavigation task from the route left in the route editor."""

    TASK_ID: str = ""
    RULESET_SPEC: Mapping[str, Any] = {}
    RULESET_SHA256: str = ""

    #: The route the instruction leaves on screen: ``(locations, mode, departure)``.
    #: ``None`` means "the unique terminal route of the declared route table".
    FINAL_ROUTE: tuple[list[str], str, str] | None = None

    # -- route contract -------------------------------------------------
    @classmethod
    def _declared_sequences(cls) -> list[dict[str, Any]]:
        rows = []
        for row in cls.RULESET_SPEC.get("route_sequences") or []:
            if not isinstance(row, Mapping):
                continue
            locations = [str(x) for x in (row.get("locations") or [])]
            modes = [str(x) for x in (row.get("modes") or [])]
            rows.append({
                "locations": locations,
                "mode": modes[-1] if modes else "",
                "departure": str(row.get("departure_setting") or "leave_now"),
            })
        return rows

    @staticmethod
    def default_departure() -> str:
        """The departure setting a route carries when the step does not state one."""
        return "leave_now"

    @classmethod
    def expected_route(cls) -> dict[str, Any] | None:
        """The route the instruction ends on."""
        if cls.FINAL_ROUTE is not None:
            locations, mode, departure = cls.FINAL_ROUTE
            return {"locations": list(locations), "mode": mode, "departure": departure}
        declared = cls._declared_sequences()
        if not declared:
            return None
        counts: dict[tuple, int] = {}
        for row in declared:
            key = (tuple(row["locations"]), row["mode"], row["departure"])
            counts[key] = counts.get(key, 0) + 1
        terminal = [row for row in declared
                    if counts[(tuple(row["locations"]), row["mode"], row["departure"])] == 1]
        return terminal[-1] if terminal else declared[-1]

    # -- state ----------------------------------------------------------
    @staticmethod
    def _ui_text(controller: Any) -> tuple[str, str, str]:
        """Foreground application, window title and the visible text of the tree."""
        if controller is None or not hasattr(controller, "observe"):
            return "", "", ""
        try:
            observation = controller.observe(include_ui_tree=True,
                                             include_screenshot_data=False)
        except Exception:  # noqa: BLE001 - no observation is an unperformed task
            return "", "", ""
        app = str(getattr(observation, "foreground_app", "")
                  or (observation.get("foreground_app") if isinstance(observation, Mapping) else "")
                  or "")
        window = str(getattr(observation, "foreground_window", "")
                     or (observation.get("foreground_window") if isinstance(observation, Mapping) else "")
                     or "")
        nodes = observation.get("ui_nodes") if isinstance(observation, Mapping) else None
        pieces: list[str] = []
        if isinstance(nodes, list):
            for node in nodes:
                if not isinstance(node, Mapping):
                    continue
                for key in ("text", "description", "value", "content_desc"):
                    value = node.get(key)
                    if value:
                        pieces.append(str(value))
        return app, window, " \u241f ".join(pieces)

    @staticmethod
    def _read_routes(controller: Any, timeout: int = 20) -> list[dict[str, Any]]:
        """Read the routes the application recorded, oldest first."""
        if controller is None or not hasattr(controller, "run_python_script"):
            return []
        script = (
            "import json, os\n"
            f"path = r'{EVENT_LOG_PATH}'\n"
            "rows = []\n"
            "if os.path.isfile(path):\n"
            "    with open(path, 'r', encoding='utf-8', errors='replace') as handle:\n"
            "        for line in handle:\n"
            "            line = line.strip()\n"
            "            if not line:\n"
            "                continue\n"
            "            try:\n"
            "                rows.append(json.loads(line))\n"
            "            except Exception:\n"
            "                pass\n"
            "print(json.dumps(rows))\n"
        )
        try:
            result = controller.run_python_script(script, timeout=timeout)
        except Exception:  # noqa: BLE001 - an unreadable log is an unperformed task
            return []
        if int(result.get("returncode", -1)) != 0:
            return []
        try:
            rows = json.loads(str(result.get("stdout") or result.get("output") or ""))
        except (TypeError, ValueError):
            return []
        return [dict(row) for row in rows if isinstance(row, Mapping)] if isinstance(rows, list) else []

    @staticmethod
    def _normalise_route(row: Mapping[str, Any]) -> dict[str, Any]:
        locations = row.get("locations") or row.get("waypoints") or []
        if isinstance(locations, str):
            locations = [part.strip() for part in locations.split("->") if part.strip()]
        origin = row.get("origin") or row.get("from")
        destination = row.get("destination") or row.get("to")
        if not locations and (origin or destination):
            locations = [str(origin or ""), str(destination or "")]
        departure = row.get("departure_setting") or row.get("departure") or "leave_now"
        if isinstance(departure, str) and departure.lower().replace(" ", "_") in (
                "leave_now", "other_time"):
            departure = departure.lower().replace(" ", "_")
        return {
            "locations": [str(x) for x in locations],
            "mode": str(row.get("mode") or row.get("travel_mode") or "").lower(),
            "departure": str(departure),
        }

    # -- judging --------------------------------------------------------
    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        return self._evaluate_task_bound(context)

    def _evaluate_task_bound(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        controller = context.get("controller")
        expected = self.expected_route()
        ui_spec = dict(self.RULESET_SPEC.get("final_ui") or {})
        checks: list[dict[str, Any]] = []

        if expected is None:
            return EvalResult(status=EvalStatus.ERROR,
                              message="no final route declared for this task",
                              metadata={"task_id": self.TASK_ID})

        raw = self._read_routes(controller, int(params.get("timeout", 20)))
        routes = [self._normalise_route(row) for row in raw]
        routes = [row for row in routes if row["locations"] or row["mode"]]
        final = routes[-1] if routes else None

        route_passed = bool(
            final
            and final["locations"] == expected["locations"]
            and final["mode"] == expected["mode"].lower()
            and final["departure"] == expected["departure"]
        )
        checks.append({
            "check_id": "final_route",
            "passed": route_passed,
            "expected": expected,
            "observed": final,
            "failure_reason": "" if route_passed else
            "the route left on screen is not the one the instruction ends on",
        })

        app, window, text = self._ui_text(controller)
        foreground_any = [str(x).casefold() for x in (ui_spec.get("foreground_any") or [])]
        foreground_ok = (not foreground_any
                         or any(name in app.casefold() or name in window.casefold()
                                for name in foreground_any))
        checks.append({
            "check_id": "final_ui.foreground",
            "passed": foreground_ok,
            "expected": ui_spec.get("foreground_any"),
            "observed": {"app": app, "window": window},
            "failure_reason": "" if foreground_ok else "the route editor is not in the foreground",
        })

        lowered = text.casefold()
        for token in (ui_spec.get("required_texts") or []):
            passed = str(token).casefold() in lowered
            checks.append({
                "check_id": f"final_ui.text.{token}",
                "passed": passed,
                "expected": token,
                "observed": passed,
                "failure_reason": "" if passed else
                f"the route editor does not show {token}",
            })
        for group in (ui_spec.get("any_text_groups") or []):
            passed = any(str(option).casefold() in lowered for option in group)
            checks.append({
                "check_id": "final_ui.any." + "|".join(str(x) for x in group),
                "passed": passed,
                "expected": list(group),
                "observed": passed,
                "failure_reason": "" if passed else
                "the route editor shows none of " + ", ".join(str(x) for x in group),
            })

        failed = [row["check_id"] for row in checks if not row["passed"]]
        metadata = {
            "task_id": self.TASK_ID,
            "read_only": True,
            "ruleset_sha256": self.RULESET_SHA256,
            "checks": checks,
            "failed_checks": failed,
            "expected_final_route": expected,
            "observed_final_route": final,
            "recorded_route_count": len(routes),
        }
        if failed:
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenNavigation evaluation failed: " + ", ".join(failed),
                              metadata=metadata)
        return EvalResult(status=EvalStatus.PASS,
                          message="OpenNavigation final route evaluation passed",
                          metadata=metadata)
